export const dynamic = 'force-dynamic'

import { NextRequest, NextResponse } from 'next/server'
import { logger } from '@/lib/logger'
import { randomBytes } from 'crypto'
import { z } from 'zod'
import { sendTemplatedEmail } from '@/lib/email-templates'
import { db } from '@/lib/db'
import { rateLimit, getClientIdentifier } from '@/lib/security/rateLimit'
import { hashPasswordResetToken } from '@/lib/auth/passwordRecovery'
import { safeRedirectPath } from '@/lib/auth/safeRedirect'

// AUTO-GENERATED by api-row-sweep --apply — REVIEW these column types.
// pg returns bigint/numeric as string, timestamptz as Date; add `| null` where nullable.
interface UserRow {
  id: string
  email: string
  full_name: string | null
}

const forgotSchema = z.object({
  email: z.string().trim().email('Invalid email address'),
  next: z.string().optional(),
})

function okResponse() {
  return NextResponse.json({
    success: true,
    message: 'If an account matches that address, you will receive a password reset link. Check your inbox and spam folder.',
  })
}

export async function POST(req: NextRequest) {
  try {
    const body: unknown = await req.json().catch(() => ({}))
    const parsed = forgotSchema.safeParse(body)
    if (!parsed.success) return okResponse()

    const email = parsed.data.email.toLowerCase().trim()
    const identifier = email || getClientIdentifier(req)
    const { allowed } = await rateLimit(`forgot:${identifier}`, 5, 15 * 60 * 1000)
    if (!allowed) {
      return NextResponse.json({ error: 'Too many requests. Please try again later.' }, { status: 429 })
    }

    const userRes = await db.query<UserRow>('SELECT id, email, full_name FROM users WHERE email = $1 LIMIT 1', [email])
    if (userRes.rows.length === 0) return okResponse()

    const user = userRes.rows[0]
    const token = randomBytes(32).toString('hex')
    const expiresAt = new Date(Date.now() + 60 * 60 * 1000)

    const tokenDigest = hashPasswordResetToken(token)
    await db.query<never>(
      `INSERT INTO password_reset_tokens (user_id, token, expires_at)
       VALUES ($1, $2, $3)`,
      [user.id, tokenDigest, expiresAt.toISOString()]
    )

    const result = await sendTemplatedEmail('passwordReset', {
      to: user.email,
      name: user.full_name ?? '',
      resetToken: token,
      expiresAt: expiresAt.toISOString(),
      nextPath: safeRedirectPath(parsed.data.next),
    })

    if (!result.success) {
      await db.query('DELETE FROM password_reset_tokens WHERE user_id = $1 AND token = $2', [user.id, tokenDigest])
      logger.warn('[forgot-password] Email provider did not accept password recovery mail.')
      return unavailableResponse()
    }

    return okResponse()
  } catch (err) {
    logger.error('[forgot-password] Error:', { error: err })
    return unavailableResponse()
  }
}

function unavailableResponse() {
  return NextResponse.json({ error: 'Password recovery is temporarily unavailable. Please try again later.' }, { status: 503 })
}
